import{_ as e,o,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Developer Monthly 2021-10-06","description":"","frontmatter":{"title":"Ceph Developer Monthly 2021-10-06","date":"2021-10-06T00:00:00.000Z","updated":"2021-10-09T00:00:00.000Z","tags":["Ceph","分布式存储","遥测","性能优化","SMR 驱动器","RBD 镜像复制"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Developer_Monthly_2021-10-06.md","filePath":"posts/2021/Ceph_Developer_Monthly_2021-10-06.md","lastUpdated":1780460162000}'),i={name:"posts/2021/Ceph_Developer_Monthly_2021-10-06.md"};function r(s,l,n,h,d,u){return o(),t("div",null,[...l[0]||(l[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-十月会议" tabindex="-1">会议主题：Ceph 十月会议 <a class="header-anchor" href="#会议主题-ceph-十月会议" aria-label="Permalink to &quot;会议主题：Ceph 十月会议&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><strong>遥测与性能信息</strong></li><li><strong>SMR 驱动器的 Boost 支持</strong></li><li><strong>RBD 镜像复制集成</strong></li></ol><h4 id="讨论内容" tabindex="-1">讨论内容： <a class="header-anchor" href="#讨论内容" aria-label="Permalink to &quot;讨论内容：&quot;">​</a></h4><h5 id="_1-遥测与性能信息" tabindex="-1">1. 遥测与性能信息 <a class="header-anchor" href="#_1-遥测与性能信息" aria-label="Permalink to &quot;1. 遥测与性能信息&quot;">​</a></h5><ul><li><strong>背景</strong>：遥测模块收集用户集群的匿名数据，用于帮助开发者了解集群使用情况和识别问题。</li><li><strong>性能通道</strong>： <ul><li><strong>收集内容</strong>：包括性能计数器、OSD 性能直方图、I/O 速率、每个池的统计总和等。</li><li><strong>目的</strong>：帮助开发者理解集群整体使用情况，发现操作分布，识别集群使用变化，以及系统是否按预期执行。</li><li><strong>决定事项</strong>： <ul><li>从按池收集改为按单个 PG 级别收集统计总和。</li><li>移除池名称以保护匿名性。</li></ul></li><li><strong>后续行动</strong>： <ul><li>添加新的指标如 mempool 和 RocksDB 压缩统计。</li><li>讨论数据不可用性的检测和相关指标的收集。</li></ul></li></ul></li></ul><h5 id="_2-smr-驱动器的-boost-支持" tabindex="-1">2. SMR 驱动器的 Boost 支持 <a class="header-anchor" href="#_2-smr-驱动器的-boost-支持" aria-label="Permalink to &quot;2. SMR 驱动器的 Boost 支持&quot;">​</a></h5><ul><li><strong>当前状态</strong>：内部元数据跟踪已实现，简单清理器已实现，Boost 可以在 SMR 硬盘上成功运行。</li><li><strong>下一步</strong>： <ul><li>确定如何构建，考虑是否添加 libzbd 库依赖。</li><li>实现更智能的清理策略。</li><li>考虑如何使用常规区域，可能让 BlueFS 使用顺序区域。</li><li>解决 fs_check 中的内存使用问题。</li><li>为 SMR 驱动器创建不同的 OSD 类别。</li></ul></li></ul><h5 id="_3-rbd-镜像复制集成" tabindex="-1">3. RBD 镜像复制集成 <a class="header-anchor" href="#_3-rbd-镜像复制集成" aria-label="Permalink to &quot;3. RBD 镜像复制集成&quot;">​</a></h5><ul><li><strong>目标</strong>：启用用户监控异步复制的健康状况，检测异常，并提供跨集群复制的统一方式来传递指标和警报。</li><li><strong>实现方式</strong>：使用 Prometheus 作为消费者，通过 HTTP 端点暴露指标。</li><li><strong>挑战与决定</strong>： <ul><li>考虑使用 Prometheus C++ 库或自定义实现。</li><li>讨论了高可用性、安全性和服务发现的问题。</li><li>决定不引入新的 Web 服务器模块，而是考虑使用 Boost Beast。</li></ul></li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>完成遥测模块的改进，特别是性能通道的指标收集和数据不可用性的检测。</li><li>继续 SMR 驱动器支持的工作，包括构建和清理策略的优化。</li><li>推进 RBD 镜像复制集成的工作，特别是 Prometheus 端点的实现和统一指标的制定。</li></ul><h4 id="结论" tabindex="-1">结论： <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论：&quot;">​</a></h4><p>会议讨论了多个关于 Ceph 的重要议题，包括遥测、性能优化、SMR 驱动器支持和 RBD 镜像复制集成。每个议题都有明确的下一步行动计划，旨在提高 Ceph 的性能和可用性。</p>',15)])])}const c=e(i,[["render",r]]);export{p as __pageData,c as default};
